// Primary Gemini model failed (e.g. 503 high demand). Re-attach the uploaded files for the backup model.
const f = $('Procurement Intake Form').first();
return [{ json: f.json, binary: f.binary }];

// Node 3 - Validate intake, parse the Gemini analysis of the uploaded quotations, and load policy.
const source = $('Procurement Intake Form').first().json;
const reviewer = String(source.reviewer_name ?? source['Reviewer Name'] ?? '').trim();
const purchaseRequest = String(source.purchase_request ?? source['Purchase Request ID'] ?? 'PR-NOVA-001').trim();
if (!reviewer) throw new Error('Reviewer name is required');
if (!/^PR-[A-Z0-9-]{3,30}$/i.test(purchaseRequest)) throw new Error('Enter a valid demo PR reference, for example PR-NOVA-001');
const requirements = {
  company: 'Nova Retail Distribution Pvt. Ltd. (fictional)',
  category: 'Wired handheld 2D barcode scanners with USB',
  quantity: 20, minimumSpecification: '2D USB',
  maxLandedBudgetINR: 145000, maxDeliveryDays: 15, minimumWarrantyMonths: 12,
  taxBasis: 'Demo-only: 18% applied to goods plus freight',
  scoreWeights: { price: 0.40, warranty: 0.25, delivery: 0.20, support: 0.15 },
  warrantyScoreCapMonths: 24, evaluationSnapshotDate: '2026-10-25'
};
const g = $input.first().json;
const raw = g?.content?.parts?.map(p => p.text || '').join('')
  ?? g?.candidates?.[0]?.content?.parts?.map(p => p.text || '').join('')
  ?? g?.text ?? (typeof g?.content === 'string' ? g.content : '');
if (!raw) throw new Error('Gemini returned no analysis for the uploaded quotations');
let parsed;
try {
  const cleaned = String(raw).replace(/^\s*\`\`\`(?:json)?/i, '').replace(/\`\`\`\s*$/, '').trim();
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  parsed = JSON.parse(cleaned.slice(firstBrace, lastBrace + 1));
} catch (e) {
  throw new Error('Could not read Gemini output as JSON: ' + String(raw).slice(0, 300));
}
const num = v => (typeof v === 'number' ? v : Number(String(v ?? '').replace(/[^0-9.\-]/g, '')));
const quotes = (parsed.quotes || []).map((q, i) => ({
  quoteId: String(q.quoteId || ('Q-' + (i + 1))),
  vendorId: String(q.vendorId || ('Vendor ' + String.fromCharCode(65 + i))),
  vendor: String(q.vendor || 'Unknown supplier'),
  quantity: num(q.quantity), unitPrice: num(q.unitPrice), freight: num(q.freight ?? 0),
  gstRate: num(q.gstRate ?? 0.18) > 1 ? num(q.gstRate) / 100 : num(q.gstRate ?? 0.18),
  warrantyMonths: num(q.warrantyMonths), deliveryDays: num(q.deliveryDays), supportOutOfTen: num(q.supportOutOfTen),
  specification: String(q.specification || ''), validUntil: String(q.validUntil || ''),
  paymentTerms: String(q.paymentTerms || ''), supportNotes: String(q.supportNotes || '')
}));
if (quotes.length === 0) throw new Error('Gemini did not find any quotations in the uploaded files');
const aiExecutiveSummary = String(parsed.aiExecutiveSummary || '');
return [{json:{reviewer,purchaseRequest,requirements,quotes,aiExecutiveSummary,fictional:true}}];

// Node 3 - Validate, compare and prepare a READ-ONLY scorecard.
const input = $input.first().json;
const {requirements:r,quotes} = input;
const round2 = n => Math.round((n + Number.EPSILON) * 100) / 100;
const esc = val => String(val).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const processed = quotes.map(q => {
  const reasons=[];
  const nums=[q.quantity,q.unitPrice,q.freight,q.gstRate,q.warrantyMonths,q.deliveryDays,q.supportOutOfTen];
  if(nums.some(x=>!Number.isFinite(x))) reasons.push('Missing or invalid numeric value');
  if(q.quantity!==r.quantity) reasons.push('Quantity must equal '+r.quantity);
  if(q.unitPrice<=0 || q.freight<0 || q.gstRate<0) reasons.push('Invalid pricing');
  if(!/2D/i.test(q.specification||'') || !/USB/i.test(q.specification||'')) reasons.push('Does not confirm wired 2D USB specification');
  if(q.warrantyMonths<r.minimumWarrantyMonths) reasons.push('Warranty below minimum');
  if(q.deliveryDays<=0 || q.deliveryDays>r.maxDeliveryDays) reasons.push('Delivery outside policy');
  if(q.supportOutOfTen<0 || q.supportOutOfTen>10) reasons.push('Support rating outside 0-10');
  const subtotal = round2(q.quantity*q.unitPrice+q.freight);
  const tax = round2(subtotal*q.gstRate);
  const landedCost = round2(subtotal+tax);
  if(landedCost>r.maxLandedBudgetINR) reasons.push('Exceeds landed budget');
  if(!q.validUntil || q.validUntil<r.evaluationSnapshotDate) reasons.push('Quote expired on the fixed 2026-10-25 snapshot');
  return {...q,subtotal,tax,landedCost,eligible:reasons.length===0,policyFlags:reasons};
});
const eligible=processed.filter(q=>q.eligible);
if(eligible.length===0) throw new Error('No eligible suppliers. Review the quote inputs and mandatory criteria; never auto-approve an exception.');
const minimumCost=Math.min(...eligible.map(q=>q.landedCost));
const fastestDays=Math.min(...eligible.map(q=>q.deliveryDays));
for (const q of processed) {
  if (!q.eligible) {q.score=null;q.scoreBreakdown=null;continue;}
  const scores = {
    price: minimumCost/q.landedCost*100,
    warranty: Math.min(q.warrantyMonths/r.warrantyScoreCapMonths,1)*100,
    delivery: fastestDays/q.deliveryDays*100,
    support: q.supportOutOfTen*10
  };
  q.scoreBreakdown=Object.fromEntries(Object.entries(scores).map(([k,v])=>[k,round2(v)]));
  q.score=round2(scores.price*r.scoreWeights.price + scores.warranty*r.scoreWeights.warranty + scores.delivery*r.scoreWeights.delivery + scores.support*r.scoreWeights.support);
}
processed.sort((a,b) => (b.eligible-a.eligible) || ((b.score??-1)-(a.score??-1)) || a.landedCost-b.landedCost || a.vendorId.localeCompare(b.vendorId));
const proposed=processed.find(q=>q.eligible);
const inr=n=>'INR '+n.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
const rows=processed.map(q=>`<tr><td style="padding:7px;border-bottom:1px solid #ddd"><b>${esc(q.vendorId)}</b> - ${esc(q.vendor)}</td><td style="padding:7px;border-bottom:1px solid #ddd">${inr(q.landedCost)}</td><td style="padding:7px;border-bottom:1px solid #ddd">${q.deliveryDays} days</td><td style="padding:7px;border-bottom:1px solid #ddd">${q.warrantyMonths} mo</td><td style="padding:7px;border-bottom:1px solid #ddd">${q.eligible?q.score.toFixed(2):'INELIGIBLE'}</td></tr>`).join('');
const reviewHtml=`<div style="font-family:Arial,sans-serif;max-width:100%"><div style="padding:12px;background:#eff6ff;border-left:4px solid #2563eb"><b>Recommended (automated, not approved): ${esc(proposed.vendorId)} - ${esc(proposed.vendor)}</b><div>Score ${proposed.score.toFixed(2)}/100 &nbsp;|&nbsp; ${inr(proposed.landedCost)} &nbsp;|&nbsp; Request ${esc(input.purchaseRequest)}</div></div>${input.aiExecutiveSummary?`<p style="font-size:12px;background:#f8fafc;padding:8px;border:1px solid #e2e8f0"><b>Gemini summary of uploaded quotations:</b> ${esc(input.aiExecutiveSummary)}</p>`:''}<p><b>Uploaded quotation comparison (20 units)</b></p><div style="overflow-x:auto"><table style="border-collapse:collapse;width:100%;font-size:12px"><tr style="background:#e2e8f0"><th style="padding:7px;text-align:left">Supplier</th><th style="padding:7px;text-align:left">Landed cost</th><th style="padding:7px">Delivery</th><th style="padding:7px">Warranty</th><th style="padding:7px">Weighted score /100</th></tr>${rows}</table></div><p style="font-size:12px">Policy: <= INR 145,000; delivery <= 15 days; warranty >= 12 months; 2D USB, 20 units. Scores: landed price 40%, warranty 25%, delivery 20%, fictional support 15%. Freight + demo GST included. Payment terms are shown for review and are not automatically prohibited.</p><p style="color:#b91c1c"><b>DEMO ONLY:</b> Choosing Approve here records a simulated procurement decision. NO order, supplier email or payment is sent. You may override with a clear reason.</p></div>`;
const reviewFormFields = [
  {fieldType:'html',html:reviewHtml},
  {fieldLabel:'Decision',fieldName:'decision',fieldType:'dropdown',fieldOptions:{values:[{option:'Approve selected vendor (SIMULATION)'},{option:'Reject all - request fresh quotes'}]},defaultValue:'Approve selected vendor (SIMULATION)',requiredField:true},
  {fieldLabel:'Selected Vendor',fieldName:'selected_vendor',fieldType:'dropdown',fieldOptions:{values:processed.map(q=>({option:q.vendorId}))},defaultValue:proposed.vendorId,requiredField:true},
  {fieldLabel:'Reason / Notes',fieldName:'review_notes',fieldType:'textarea',placeholder:'Required (10+ characters) if you choose a vendor other than '+proposed.vendorId+' or reject all quotes.'}
];
return [{json:{...input,quotes:processed,proposedVendorId:proposed.vendorId,proposedVendorName:proposed.vendor,proposedScore:proposed.score,reviewHtml,reviewFormFields,scoringAsOf:r.evaluationSnapshotDate}}];

// Node 5 - Enforce human-in-the-loop constraints and make a demo-only audit record.
const form=$input.first().json;
const analysis=$('Score and Prepare Review').first().json;
const decision=String(form.decision??form['Decision']??'').trim();
const selected=String(form.selected_vendor??form['Selected Vendor']??'').trim();
const reason=String(form.review_notes??form['Reason / Notes']??'').trim();
const reject=decision==='Reject all - request fresh quotes';
const approve=decision==='Approve selected vendor (SIMULATION)';
if(!approve&&!reject) throw new Error('Please choose approve or reject');
const match=analysis.quotes.find(q=>q.vendorId===selected);
if(approve && (!match || !match.eligible)) throw new Error('The selected vendor is not an eligible supplier under this training policy');
const overridden=approve && selected!==analysis.proposedVendorId;
if((overridden||reject)&&reason.length<10) {
  const why = reject
    ? 'You chose to reject all quotes'
    : `You selected ${selected}, but the system recommended ${analysis.proposedVendorId}`;
  return [{json:{valid:false,completionTitle:'Decision NOT recorded - reason required',completionMessage:`${why}. An override or rejection needs a reason of at least 10 characters in "Reason / Notes". Nothing was recorded. Please submit the purchase request again and add your reason, or keep the recommended vendor.`,trainingOnly:true}}];
}
const status=reject?'REJECTED_FOR_DEMO':'APPROVED_FOR_DEMO';
const approvedVendor=reject?'':selected;
const auditRecord={
  timestamp:new Date().toISOString(), purchaseRequest:analysis.purchaseRequest,
  reviewer:analysis.reviewer, systemRecommendation:analysis.proposedVendorId,
  recommendationScore:analysis.proposedScore,
  decision:status,selectedVendor:approvedVendor,
  isOverride:overridden,overrideReason:reason,
  selectedLandedCostINR:approve?match.landedCost:null,
  selectedScore:approve?match.score:null, trainingOnly:true,
  actionTaken:'RECORD SIMULATED REVIEW ONLY - NO PO, NO EMAIL, NO PAYMENT'
};
const message=reject
  ?`Request ${analysis.purchaseRequest} was rejected for DEMO purposes. New quotes required. Reviewer: ${analysis.reviewer}. No order placed.`
  :`Request ${analysis.purchaseRequest}: ${selected} ${overridden?'(human override)':'(system recommendation accepted)'} recorded as APPROVED FOR SIMULATION by ${analysis.reviewer}. No purchase order or payment was created.`;
return [{json:{valid:true,completionTitle:'Decision recorded - training simulation',auditRecord,completionMessage:message,proposal:analysis.proposedVendorId,comparison:analysis.quotes.map(q=>({vendor:q.vendorId,landedCostINR:q.landedCost,score:q.score,eligible:q.eligible})),trainingOnly:true}}];
